/// Toneless pinyin of a Chinese name, so "小明", "晓明" and "Xiao Ming"
/// read alike. Non-Chinese characters pass through; one reading each.
String pinyinOf(String name, {bool surnameFirst = true}) {
  final out = StringBuffer();
  final runes = name.runes.toList();
  for (final (i, r) in runes.indexed) {
    final ch = String.fromCharCode(r);
    out.write(
      (i == 0 && surnameFirst ? _surnames[ch] : null) ?? _reading[ch] ?? ch,
    );
  }
  return out.toString();
}

bool hasHan(String s) => _han.hasMatch(s);

final _han = RegExp(r'[一-鿿]');

/// Surnames read apart from the character's usual reading.
const _surnames = {
  '曾': 'zeng',
  '单': 'shan',
  '解': 'xie',
  '区': 'ou',
  '仇': 'qiu',
  '朴': 'piao',
  '查': 'zha',
  '盖': 'ge',
  '尉': 'yu',
  '乐': 'yue',
  '覃': 'qin',
  '翟': 'zhai',
  '缪': 'miao',
  '长': 'chang',
  '重': 'chong',
  '沈': 'shen',
  '石': 'shi',
  '柏': 'bai',
  '莘': 'shen',
};

final Map<String, String> _reading = () {
  final out = <String, String>{};
  var syllable = '';
  for (final m in RegExp(r'([a-z]+)|(.)').allMatches(_table)) {
    if (m[1] case final s?) {
      syllable = s;
    } else {
      out[m[2]!] = syllable;
    }
  }
  return out;
}();

